  (* [comment removed for export] *)
  Lemma strlen_words : forall (k : nat) (j : Z) (a5 a6 : word),
    (Z.to_nat (len - j) = k) -> (0 <= j <= len)%Z -> ((A + j) mod 8 = 0)%Z ->
